package com.awesomeclan;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AwesomeClanConfig.GROUP)
public interface AwesomeClanConfig extends Config
{
	String GROUP = "awesomeclan";

	@ConfigSection(
		name = "Notifications",
		description = "Pop-ups for new votes, competitions and event signups",
		position = 10
	)
	String notificationsSection = "notifications";

	@ConfigItem(
		keyName = "pluginToken",
		name = "Plugin tokens",
		description = "Your token from the dashboard profile page. If you play more than one account, put each account's token on its own line. The plugin does nothing without a token.",
		position = 0
	)
	default String pluginToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "relayClanChat",
		name = "Relay clan chat",
		description = "Send clan chat and clan broadcasts to the dashboard",
		warning = "This sends all AwesomeClan clan chat you see, including other members' messages, to the dashboard where staff can read it. Public chat and PMs are never sent. Turn it on?",
		position = 1
	)
	default boolean relayClanChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showNotifications",
		name = "Show notifications",
		description = "Show a pop-up in game when the clan starts a vote, competition or event signup",
		section = notificationsSection,
		position = 0
	)
	default boolean showNotifications()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notificationDuration",
		name = "Pop-up duration",
		description = "How long each pop-up stays on screen",
		section = notificationsSection,
		position = 1
	)
	@Range(min = 3, max = 30)
	@Units(Units.SECONDS)
	default int notificationDuration()
	{
		return 6;
	}

	@ConfigItem(
		keyName = "notificationChatMessage",
		name = "Chat message",
		description = "Also put the notification in your chatbox",
		section = notificationsSection,
		position = 2
	)
	default boolean notificationChatMessage()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notificationDesktop",
		name = "Desktop notification",
		description = "Also send a RuneLite desktop notification",
		section = notificationsSection,
		position = 3
	)
	default Notification notificationDesktop()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "notifyVotes",
		name = "Votes",
		description = "New clan and competition votes",
		section = notificationsSection,
		position = 4
	)
	default boolean notifyVotes()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyCompetitions",
		name = "Competitions",
		description = "When a clan competition starts",
		section = notificationsSection,
		position = 5
	)
	default boolean notifyCompetitions()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyBingo",
		name = "Bingo",
		description = "When bingo signups open",
		section = notificationsSection,
		position = 6
	)
	default boolean notifyBingo()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyBattleship",
		name = "Battleship",
		description = "When battleship signups open",
		section = notificationsSection,
		position = 7
	)
	default boolean notifyBattleship()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyOther",
		name = "Events & announcements",
		description = "Mass events and other clan announcements",
		section = notificationsSection,
		position = 8
	)
	default boolean notifyOther()
	{
		return true;
	}
}

package com.awesomeclan;

import com.awesomeclan.api.ApiClient;
import com.awesomeclan.clan.ClanBroadcastTracker;
import com.awesomeclan.clan.ClanChatRelay;
import com.awesomeclan.clan.CofferBalanceReader;
import com.awesomeclan.live.LiveDataTracker;
import com.awesomeclan.notify.NotificationOverlay;
import com.awesomeclan.notify.NotificationPoller;
import com.awesomeclan.roster.RosterCollector;
import com.google.inject.Provides;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanSettings;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "AwesomeClan",
	description = "Keeps the AwesomeClan roster synced with the clan website, pops up clan votes, competitions and event signups, and optionally shows your XP/boss kills live and relays clan chat to the dashboard",
	tags = {"clan", "roster", "awesomeclan"}
)
public class AwesomeClanPlugin extends Plugin
{
	public static final String CLAN_NAME = "AwesomeClan";

	private static final int SYNC_CHECK_MINUTES = 5;
	private static final int SYNC_INTERVAL_MINUTES = 20;
	private static final int SYNC_JITTER_MINUTES = 10;
	private static final int LIVE_FLUSH_PERIOD_SECONDS = 15;
	private static final int CHAT_FLUSH_PERIOD_SECONDS = 5;
	private static final int NOTIFICATION_POLL_SECONDS = 30;

	@Inject
	private Client client;

	@Inject
	private ApiClient api;

	@Inject
	private EventBus eventBus;

	@Inject
	private LiveDataTracker liveDataTracker;

	@Inject
	private ClanBroadcastTracker clanBroadcastTracker;

	@Inject
	private CofferBalanceReader cofferBalanceReader;

	@Inject
	private ClanChatRelay clanChatRelay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NotificationOverlay notificationOverlay;

	@Inject
	private NotificationPoller notificationPoller;

	private Instant nextSyncAt;

	@Provides
	AwesomeClanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AwesomeClanConfig.class);
	}

	@Override
	protected void startUp()
	{
		nextSyncAt = nextSyncTime();
		eventBus.register(liveDataTracker);
		eventBus.register(clanBroadcastTracker);
		eventBus.register(cofferBalanceReader);
		eventBus.register(clanChatRelay);
		overlayManager.add(notificationOverlay);
	}

	@Override
	protected void shutDown()
	{
		nextSyncAt = null;
		liveDataTracker.flushOnShutdown();
		clanChatRelay.flush();
		eventBus.unregister(liveDataTracker);
		eventBus.unregister(clanBroadcastTracker);
		eventBus.unregister(cofferBalanceReader);
		eventBus.unregister(clanChatRelay);
		overlayManager.remove(notificationOverlay);
		notificationOverlay.clear();
		liveDataTracker.reset();
		clanChatRelay.reset();
	}

	@Schedule(period = LIVE_FLUSH_PERIOD_SECONDS, unit = ChronoUnit.SECONDS)
	public void flushLiveData()
	{
		liveDataTracker.flushPeriodic();
	}

	@Schedule(period = CHAT_FLUSH_PERIOD_SECONDS, unit = ChronoUnit.SECONDS)
	public void flushClanChat()
	{
		clanChatRelay.flush();
	}

	@Schedule(period = NOTIFICATION_POLL_SECONDS, unit = ChronoUnit.SECONDS)
	public void pollNotifications()
	{
		notificationPoller.poll();
	}

	@Schedule(period = SYNC_CHECK_MINUTES, unit = ChronoUnit.MINUTES)
	public void trySync()
	{
		if (nextSyncAt == null || Instant.now().isBefore(nextSyncAt))
		{
			return;
		}

		nextSyncAt = nextSyncTime();

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		ClanSettings clanSettings = client.getClanSettings();
		if (clanSettings == null || clanSettings.getMembers() == null || clanSettings.getMembers().isEmpty())
		{
			return;
		}

		if (!CLAN_NAME.equalsIgnoreCase(clanSettings.getName()))
		{
			return;
		}

		api.post("clan/roster", RosterCollector.collect(clanSettings));
	}

	public static boolean inClan(Client client)
	{
		ClanChannel channel = client.getClanChannel();
		return channel != null && CLAN_NAME.equalsIgnoreCase(channel.getName());
	}

	private static Instant nextSyncTime()
	{
		int jitterSeconds = ThreadLocalRandom.current().nextInt(0, SYNC_JITTER_MINUTES * 60);
		return Instant.now().plusSeconds(SYNC_INTERVAL_MINUTES * 60L + jitterSeconds);
	}
}

package com.awesomeclan.api;

import com.awesomeclan.AwesomeClanConfig;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@Singleton
public class ApiClient
{
	private static final HttpUrl BASE_URL = HttpUrl.parse("https://api.awesomeclan.com/api/");
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	@Inject
	private Gson gson;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private AwesomeClanConfig config;

	public List<String> tokens()
	{
		return PluginTokens.parse(config.pluginToken());
	}

	// clan-wide stuff, any of the tokens works so just use the first
	public void post(String path, Object payload)
	{
		List<String> tokens = tokens();
		if (tokens.isEmpty())
		{
			return;
		}

		newCall(path, payload, tokens.get(0)).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				log.warn("POST {} failed", path, e);
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				response.close();
				if (!response.isSuccessful())
				{
					log.warn("POST {} failed with HTTP {}", path, response.code());
				}
			}
		});
	}

	public Call newCall(String path, Object payload, String token)
	{
		Request request = new Request.Builder()
			.url(BASE_URL.resolve(path))
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.header("Authorization", "Bearer " + token)
			.build();
		return okHttpClient.newCall(request);
	}

	public Call newGet(HttpUrl url, String token)
	{
		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.build();
		return okHttpClient.newCall(request);
	}

	public static HttpUrl url(String path)
	{
		return BASE_URL.resolve(path);
	}
}

package com.awesomeclan.api;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public final class PluginTokens
{
	private PluginTokens()
	{
	}

	public static List<String> parse(String raw)
	{
		if (raw == null)
		{
			return List.of();
		}

		return Arrays.stream(raw.split("\\r?\\n"))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.toList());
	}
}

package com.awesomeclan.clan;

import com.awesomeclan.AwesomeClanPlugin;
import com.awesomeclan.api.ApiClient;
import com.awesomeclan.util.AccountId;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Slf4j
public class ClanBroadcastTracker
{
	private static final Pattern KICK = Pattern.compile("^(.+?) has expelled (.+?) from the clan\\.$");
	private static final Pattern RECRUIT = Pattern.compile("^(.+?) has been invited into the clan by (.+?)\\.?$");
	private static final Pattern DEPOSIT = Pattern.compile("^(.+?) has deposited ([0-9,]+) coins? into the coffer\\.$");
	private static final Pattern WITHDRAW = Pattern.compile("^(.+?) has withdrawn ([0-9,]+) coins? from the coffer\\.$");

	@Inject
	private Client client;

	@Inject
	private ApiClient api;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.CLAN_MESSAGE || !AwesomeClanPlugin.inClan(client))
		{
			return;
		}

		String message = Text.removeTags(event.getMessage()).trim();
		Matcher m;
		if ((m = KICK.matcher(message)).matches())
		{
			api.post("clan/kick", new Kick(AwesomeClanPlugin.CLAN_NAME, m.group(2).trim(), m.group(1).trim()));
		}
		else if ((m = RECRUIT.matcher(message)).matches())
		{
			api.post("clan/recruit", new Recruit(AwesomeClanPlugin.CLAN_NAME, m.group(1).trim(), m.group(2).trim()));
		}
		else if ((m = DEPOSIT.matcher(message)).matches())
		{
			reportCoffer(m, "deposit");
		}
		else if ((m = WITHDRAW.matcher(message)).matches())
		{
			reportCoffer(m, "withdraw");
		}
	}

	private void reportCoffer(Matcher m, String type)
	{
		long amount;
		try
		{
			amount = Long.parseLong(m.group(2).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			log.debug("Bad coffer amount: {}", m.group(2));
			return;
		}

		// everyone online sends this, server dedupes on account id
		String accountId = AccountId.of(client.getAccountHash());
		api.post("clan/coffer", new CofferTransaction(AwesomeClanPlugin.CLAN_NAME, accountId, m.group(1).trim(), amount, type));
	}

	@Value
	private static class Kick
	{
		String clanName;
		String kickedName;
		String kickedBy;
	}

	@Value
	private static class Recruit
	{
		String clanName;
		String recruitedName;
		String recruitedBy;
	}

	@Value
	private static class CofferTransaction
	{
		String clanName;
		String accountId;
		String memberName;
		long amount;
		String type;
	}
}

package com.awesomeclan.clan;

import com.awesomeclan.AwesomeClanConfig;
import com.awesomeclan.AwesomeClanPlugin;
import com.awesomeclan.api.ApiClient;
import com.awesomeclan.util.AccountId;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Singleton
public class ClanChatRelay
{
	private static final int MAX_BATCH = 50;
	private static final int MAX_QUEUED = 200;
	// shown to you on login, not real chat
	private static final String CLAN_CHAT_HINT = "To talk in your clan's channel, start each line of chat with // or /c.";

	@Inject
	private Client client;

	@Inject
	private ApiClient api;

	@Inject
	private AwesomeClanConfig config;

	private final List<RelayedMessage> queue = new ArrayList<>();

	// kept so the last batch after logout still has it
	private String accountId;

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.CLAN_CHAT && type != ChatMessageType.CLAN_MESSAGE)
		{
			return;
		}
		if (!config.relayClanChat() || !AwesomeClanPlugin.inClan(client))
		{
			return;
		}

		String message = Text.removeTags(event.getMessage()).trim();
		if (message.isEmpty() || (type == ChatMessageType.CLAN_MESSAGE && message.equalsIgnoreCase(CLAN_CHAT_HINT)))
		{
			return;
		}

		RelayedMessage relayed = type == ChatMessageType.CLAN_CHAT
			? new RelayedMessage("chat", Text.sanitize(event.getName()).trim(), message)
			: new RelayedMessage("broadcast", null, message);

		synchronized (queue)
		{
			accountId = AccountId.of(client.getAccountHash());
			if (queue.size() >= MAX_QUEUED)
			{
				queue.remove(0);
			}
			queue.add(relayed);
		}
	}

	public void flush()
	{
		List<RelayedMessage> batch;
		String batchAccountId;
		synchronized (queue)
		{
			if (queue.isEmpty())
			{
				return;
			}
			int n = Math.min(queue.size(), MAX_BATCH);
			batch = new ArrayList<>(queue.subList(0, n));
			queue.subList(0, n).clear();
			batchAccountId = accountId;
		}

		api.post("clan/chat", new ClanChatBatch(AwesomeClanPlugin.CLAN_NAME, batchAccountId, batch));
	}

	public void reset()
	{
		synchronized (queue)
		{
			queue.clear();
			accountId = null;
		}
	}

	@Value
	private static class RelayedMessage
	{
		String type;
		String sender;
		String message;
	}

	@Value
	private static class ClanChatBatch
	{
		String clanName;
		String accountId;
		List<RelayedMessage> messages;
	}
}

package com.awesomeclan.clan;

import com.awesomeclan.AwesomeClanPlugin;
import com.awesomeclan.api.ApiClient;
import javax.inject.Inject;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

// Corrects the coffer total on the site in case a broadcast got missed
public class CofferBalanceReader
{
	@Inject
	private Client client;

	@Inject
	private ApiClient api;

	private int readDelay = -1;

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CLANS_STORAGE_MAIN)
		{
			// items aren't populated on the tick the widget loads
			readDelay = 2;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (readDelay < 0 || --readDelay > 0)
		{
			return;
		}
		readDelay = -1;

		if (!AwesomeClanPlugin.inClan(client))
		{
			return;
		}

		Widget items = client.getWidget(InterfaceID.ClansStorageMain.ITEMS);
		if (items == null || items.getDynamicChildren() == null)
		{
			return;
		}

		for (Widget child : items.getDynamicChildren())
		{
			if (child.getItemId() == ItemID.COINS)
			{
				api.post("clan/coffer-balance", new CofferBalance(AwesomeClanPlugin.CLAN_NAME, child.getItemQuantity()));
				return;
			}
		}
	}

	@Value
	private static class CofferBalance
	{
		String clanName;
		long balance;
	}
}

package com.awesomeclan.live;

import com.awesomeclan.util.AccountId;
import java.util.Collections;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.util.Text;

@Slf4j
public class LiveDataTracker
{
	// server uses the hiscores names
	private static final Map<String, String> SKILL_NAME_OVERRIDES = Map.of("Runecraft", "Runecrafting");

	// not main hiscores
	private static final Set<WorldType> IGNORED_WORLDS = EnumSet.of(
		WorldType.SEASONAL,
		WorldType.DEADMAN,
		WorldType.BETA_WORLD,
		WorldType.TOURNAMENT_WORLD,
		WorldType.NOSAVE_MODE,
		WorldType.FRESH_START_WORLD,
		WorldType.QUEST_SPEEDRUNNING,
		WorldType.PVP_ARENA,
		WorldType.LAST_MAN_STANDING
	);

	private static final long FULL_SYNC_INTERVAL_MS = 5 * 60 * 1000;

	// "Your Zulrah kill count is: 412."
	// "Your completed Chambers of Xeric count is: 5."
	private static final Pattern KILL_COUNT_PATTERN = Pattern.compile(
		"^Your (?:completed |subdued )?(.+?) (?:kill |chest |completion |success |harvest )?count is: ([0-9,]+)\\.?$",
		Pattern.CASE_INSENSITIVE
	);

	// "You have completed 12 medium Treasure Trails."
	private static final Pattern CLUE_COUNT_PATTERN = Pattern.compile(
		"^You have completed ([0-9,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.$",
		Pattern.CASE_INSENSITIVE
	);

	// "Amount of rifts you have closed: 24."
	private static final Pattern RIFTS_PATTERN = Pattern.compile(
		"^Amount of rifts you have closed: ([0-9,]+)\\.?$",
		Pattern.CASE_INSENSITIVE
	);

	@Inject
	private Client client;

	@Inject
	private LiveUploader uploader;

	private final Map<String, Integer> lastKnownSkillXp = new LinkedHashMap<>();
	private final Map<String, Integer> pendingSkillXp = new LinkedHashMap<>();
	private final Map<String, Integer> pendingBossKc = new LinkedHashMap<>();
	private final Map<String, Integer> pendingActivities = new LinkedHashMap<>();

	private long cachedAccountHash = -1;
	private String cachedAccountId;
	private String lastRsn;
	private long lastFullSync;
	// world type can already be the new world while hopping
	private boolean ignoredWorld;

	public void reset()
	{
		lastKnownSkillXp.clear();
		clearPending();
		lastFullSync = 0;
		uploader.reset();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		String name = canonicalSkillName(event.getSkill());
		int xp = event.getXp();

		Integer previous = lastKnownSkillXp.put(name, xp);
		// skip the login sync and boosts/drains
		if (previous == null || previous == xp)
		{
			return;
		}

		pendingSkillXp.put(name, xp);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		try
		{
			Matcher matcher = KILL_COUNT_PATTERN.matcher(message);
			if (matcher.matches())
			{
				pendingBossKc.put(matcher.group(1).trim(), parseCount(matcher.group(2)));
				return;
			}

			matcher = CLUE_COUNT_PATTERN.matcher(message);
			if (matcher.matches())
			{
				pendingActivities.put("Clue Scrolls (" + matcher.group(2).toLowerCase() + ")", parseCount(matcher.group(1)));
				return;
			}

			matcher = RIFTS_PATTERN.matcher(message);
			if (matcher.matches())
			{
				pendingActivities.put("Rifts closed", parseCount(matcher.group(1)));
			}
		}
		catch (NumberFormatException e)
		{
			log.debug("Bad count: {}", message);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		// hiscores update on hop as well as logout
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			flush(true);
			reset();
		}
		else if (state == GameState.LOGGED_IN)
		{
			flush(false);
		}
	}

	public void flushPeriodic()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			flush(false);
		}
	}

	public void flushOnShutdown()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			flush(true);
		}
	}

	// closing the client doesn't call shutDown
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		CompletableFuture<Void> future = flush(true);
		if (future != null)
		{
			event.waitFor(future);
		}
	}

	private CompletableFuture<Void> flush(boolean loggedOut)
	{
		if (!loggedOut)
		{
			ignoredWorld = onIgnoredWorld();
		}
		if (ignoredWorld)
		{
			clearPending();
			return null;
		}

		String rsn = currentRsn();
		if (rsn == null)
		{
			return null;
		}

		if (!loggedOut)
		{
			addFullSyncIfDue();
		}

		LivePayload payload = new LivePayload(
			rsn,
			accountId(),
			loggedOut,
			new LinkedHashMap<>(pendingSkillXp),
			new LinkedHashMap<>(pendingBossKc),
			new LinkedHashMap<>(pendingActivities)
		);

		CompletableFuture<Void> future = uploader.upload(payload);
		clearPending();
		return future;
	}

	private void clearPending()
	{
		pendingSkillXp.clear();
		pendingBossKc.clear();
		pendingActivities.clear();
	}

	// server needs every skill for Overall
	private void addFullSyncIfDue()
	{
		long now = System.currentTimeMillis();
		if (now - lastFullSync < FULL_SYNC_INTERVAL_MS)
		{
			return;
		}
		// not loaded yet
		if (client.getSkillExperience(Skill.HITPOINTS) <= 0)
		{
			return;
		}

		for (Skill skill : Skill.values())
		{
			pendingSkillXp.put(canonicalSkillName(skill), client.getSkillExperience(skill));
		}
		lastFullSync = now;
	}

	private boolean onIgnoredWorld()
	{
		EnumSet<WorldType> types = client.getWorldType();
		return types != null && !Collections.disjoint(types, IGNORED_WORLDS);
	}

	// no local player while hopping
	private String currentRsn()
	{
		if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
		{
			String name = client.getLocalPlayer().getName().trim();
			if (!name.isEmpty())
			{
				lastRsn = name;
				return name;
			}
		}
		return client.getGameState() == GameState.HOPPING ? lastRsn : null;
	}

	// can change if you switch accounts without restarting
	private String accountId()
	{
		long hash = client.getAccountHash();
		if (hash != cachedAccountHash)
		{
			cachedAccountHash = hash;
			cachedAccountId = AccountId.of(hash);
		}
		return cachedAccountId;
	}

	private static int parseCount(String raw)
	{
		return Integer.parseInt(raw.replace(",", ""));
	}

	private static String canonicalSkillName(Skill skill)
	{
		String name = skill.getName();
		return SKILL_NAME_OVERRIDES.getOrDefault(name, name);
	}
}

